{
  "medios": [
    {
      "nombre": "El País",
      "alarmismo": 45,
      "omision": 30,
      "framing": "Enfoque en la incertidumbre científica",
      "tecnicas": [
        "uso de titulares con adjetivos de incertidumbre",
        "selección de citas de expertos que resaltan riesgos potenciales",
        "inclusión de gráficos con escalas amplias que amplifican la variabilidad"
      ]
    },
    {
      "nombre": "El Mundo",
      "alarmismo": 60,
      "omision": 20,
      "framing": "Narrativa de urgencia climática",
      "tecnicas": [
        "empleo de imágenes impactantes de eventos climáticos extremos",
        "uso de comparaciones históricas que resaltan tendencias ascendentes",
        "destacar declaraciones de activistas que llaman a acciones inmediatas"
      ]
    },
    {
      "nombre": "ABC",
      "alarmismo": 35,
      "omision": 50,
      "framing": "Perspectiva de estabilidad económica",
      "tecnicas": [
        "enfatizar datos económicos que sugieren menor impacto financiero",
        "citar fuentes institucionales que minimizan consecuencias a corto plazo",
        "omisión de testimonios de comunidades vulnerables"
      ]
    }
  ],
  "comparativa": "Los tres medios presentan el mismo hecho, pero varían en el grado de alarmismo y omisión. El Mundo tiende a enfatizar la urgencia mediante imágenes y citas activistas, mientras que El País se centra en la incertidumbre científica. ABC muestra una menor carga alarmista y una mayor omisión de voces vulnerables, enfocándose en la estabilidad económica.",
  "recomendacion_ciudadana": [
    "Busca fuentes diversas y complementa la información con datos oficiales.",
    "Analiza los gráficos y los titulares para identificar posibles ampliaciones de la variabilidad.",
    "Considera tanto los riesgos resaltados como los aspectos que podrían estar menos presentes en la cobertura."
  ]
}
